```csharp
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // ──── CalculateTotal: DataRow for simple inline cases ────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "Two items, 10% tax")]
    [DataRow(0.00, 3, 0.20, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.05, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.0, "unitPrice")]
    [DataRow(10.00, -1, 0.0, "quantity")]
    [DataRow(10.00, 1, -0.1, "taxRate")]
    [DataRow(10.00, 1, 1.5, "taxRate")]
    public void CalculateTotal_WithInvalidInputs_Throws(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // ──── ApplyDiscount: DynamicData with ValueTuples for type safety ────

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10m, 90m),
        (200m, 25m, 150m),
        (50m, 0m, 50m),
        (80m, 100m, 0m),
        (0m, 50m, 0m),
    ];

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Negative discount")]
    [DataRow(101.0, DisplayName = "Over 100% discount")]
    public void ApplyDiscount_WithInvalidPercent_Throws(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }

    // ──── FormatPrice: DataRow for string output ────

    [TestMethod]
    [DataRow(19.99, "$", "$19.99")]
    [DataRow(5.5, "€", "€5.50")]
    [DataRow(0.0, "$", "$0.00")]
    public void FormatPrice_WithSymbol_ReturnsFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}
```

**Key patterns demonstrated:**

| Pattern | Where | Why |
|---------|-------|-----|
| `[DataRow]` | `CalculateTotal`, `FormatPrice` | Quick inline data; uses `double` because `DataRow` can't hold `decimal` literals |
| `[DynamicData]` + ValueTuple | `ApplyDiscount` | Type-safe `decimal` values without casting; cleaner for complex data |
| `Assert.ThrowsExactly<T>` | Invalid-input tests | Modern replacement for `[ExpectedException]`; lets you verify `ParamName` |
| Sealed class + `readonly` field | Class structure | MSTest best practice for performance and design clarity |
| `DisplayName` | Select `DataRow` entries | Readable test names in Test Explorer |

> **Note:** `DataRow` only supports compile-time constants (`int`, `double`, `string`, `bool`…), so `decimal` values must be passed as `double` and cast. `DynamicData` with ValueTuples avoids this limitation entirely—prefer it when you need `decimal` or complex types.
